if SERVER then cleanup.Register("grm_network_devices")end
TOOL.Category = "GRM";TOOL.Name = "#tool.grm_network_tool.name";TOOL.Command=nil;TOOL.ConfigName="";TOOL.ClientConVar={mode="spawn",kind="computer",model="models/natalya/sims/computer.mdl",name="Рабочая станция",network="GRM-NET"}
if CLIENT then language.Add("tool.grm_network_tool.name", "GRM Электроника и сеть");language.Add("tool.grm_network_tool.desc","Устройства, Wi-Fi и физические кабели");language.Add("tool.grm_network_tool.0","Spawn: ЛКМ создать · Link: ЛКМ/ПКМ соединить · ПКМ по устройству настроить · R убрать кабели")end
local function device(e)return IsValid(e)and string.StartWith(e:GetClass(),"grm_net_")and e:GetClass()~="grm_net_document"end
function TOOL:LeftClick(tr)if CLIENT then return true end;local p=self:GetOwner();if not p:IsSuperAdmin()then return false end;local mode=self:GetClientInfo("mode");if mode=="link"then if not device(tr.Entity)then return false end;self.LinkFirst=tr.Entity;self:SetStage(1);GRM.Notify(p,"Первый узел: "..tr.Entity:GetDisplayName()..". ПКМ по второму.",100,190,255);return true end;local kind=self:GetClientInfo("kind");local e=GRM.Electronics.SpawnDevice(kind,self:GetClientInfo("model"),tr.HitPos+tr.HitNormal*8,Angle(0,p:EyeAngles().y+180,0),p);if IsValid(e)then e:SetDisplayName(self:GetClientInfo("name"));e:SetNetworkID(self:GetClientInfo("network"));GRM.Electronics.SaveMap();undo.Create("GRM Network Device");undo.AddEntity(e);undo.SetPlayer(p);undo.Finish();cleanup.Add(p,"grm_network_devices",e);GRM.Notify(p,"Устройство установлено · Z отменит установку",100,220,130);return true end return false end
function TOOL:RightClick(tr)if CLIENT then return true end;local p=self:GetOwner();if not p:IsSuperAdmin()or not device(tr.Entity)then return false end;if self:GetClientInfo("mode")=="link"and IsValid(self.LinkFirst)then local ok,id=GRM.Electronics.Link(self.LinkFirst,tr.Entity);if ok and id then undo.Create("GRM Network Cable");undo.AddFunction(function(_,linkID)if GRM.Electronics then GRM.Electronics.RemoveLink(linkID)end end,id);undo.SetPlayer(p);undo.Finish()end;self.LinkFirst=nil;self:SetStage(0);GRM.Notify(p,ok and"Кабель соединён"or"Соединение уже существует",ok and 100 or 255,ok and 220 or 150,100);return ok end;GRM.Electronics.OpenAdmin(p,tr.Entity);return true end
function TOOL:Reload(tr)if CLIENT then return true end;local p=self:GetOwner();if not p:IsSuperAdmin()or not device(tr.Entity)then return false end;if p:KeyDown(IN_SPEED)then GRM.Electronics.UnlinkDevice(tr.Entity);tr.Entity:Remove();GRM.Electronics.SaveMap();GRM.Notify(p,"Устройство и кабели удалены",255,150,90)else local n=GRM.Electronics.UnlinkDevice(tr.Entity);GRM.Notify(p,"Удалено кабелей: "..n,255,190,90)end;return true end
if CLIENT then function TOOL.BuildCPanel(p)p:AddControl("Header",{Description="Единый конструктор GRM Internet: компьютеры, роутеры, принтеры, розетки, штекеры и кабели."});local mode=p:ComboBox("Режим","grm_network_tool_mode");mode:AddChoice("Установка устройства","spawn");mode:AddChoice("Соединение кабелем","link");local kind=p:ComboBox("Устройство","grm_network_tool_kind");kind:AddChoice("Компьютер Sims","computer");kind:AddChoice("Компьютер Office","computer");kind:AddChoice("Wi-Fi роутер","router");kind:AddChoice("Сетевой принтер","printer");kind:AddChoice("Розетка","socket");kind:AddChoice("Штекер","plug");kind.OnSelect=function(_,_,value,data)local models={computer=string.find(value,"Office",1,true)and"models/props/cs_office/computer.mdl"or"models/natalya/sims/computer.mdl",router="models/cheeze/wires/router.mdl",printer="models/props_interiors/printer.mdl",socket="models/props_lab/tpplugholder_single.mdl",plug="models/props_lab/incubatorplug.mdl"};RunConsoleCommand("grm_network_tool_kind",data);RunConsoleCommand("grm_network_tool_model",models[data]or"")end;p:TextEntry("Модель","grm_network_tool_model");p:TextEntry("Название","grm_network_tool_name");p:TextEntry("Сеть / SSID","grm_network_tool_network");p:Help("Модели:\nmodels/natalya/sims/computer.mdl\nmodels/props/cs_office/computer.mdl\nmodels/cheeze/wires/router.mdl\nmodels/props_lab/incubatorplug.mdl\nmodels/props_lab/tpplugholder_single.mdl\n\nПКМ по устройству — настройки интеграций. R — убрать кабели. Shift+R — удалить устройство.")end end
